// ControlServiceHandler is an implementation of the ladulas.v1.ControlService service.
type ControlServiceHandler interface {
	// Status reports what the instance is doing, including which peers are
	// currently reachable — which only the process holding the links knows.
	//
	// It is one of the two calls a sealed instance still answers (§10, §14):
	// saying what state the store is in needs no store.
	Status(context.Context, *connect.Request[ladulasv1.StatusRequest]) (*connect.Response[ladulasv1.StatusResponse], error)
	// Initialize creates the store and the instance identity key on a daemon
	// that has neither, and leaves it unlocked and fully serving — no restart,
	// because the process that made the store is the process that owns it.
	//
	// It is the other call an instance with no store answers, and the only way a
	// store is ever created: nothing outside the daemon writes store.age.
	Initialize(context.Context, *connect.Request[ladulasv1.InitializeRequest]) (*connect.Response[ladulasv1.InitializeResponse], error)
	// Unlock brings the data encryption key back, or lifts a soft lock. The
	// passphrase travels over the uid-checked socket and the daemon derives the
	// key encryption key from it (§14); an empty passphrase means "use the
	// keychain", which is the enrolled instance's way in.
	//
	// The other call a sealed instance answers.
	Unlock(context.Context, *connect.Request[ladulasv1.UnlockRequest]) (*connect.Response[ladulasv1.UnlockResponse], error)
	// Lock suspends local approval authority, or — with seal — wipes the data
	// encryption key. A soft lock leaves remote approval working, which is the
	// whole point of it (§10).
	Lock(context.Context, *connect.Request[ladulasv1.LockRequest]) (*connect.Response[ladulasv1.LockResponse], error)
	// AwaitState holds the call open until this instance is in one of the states
	// asked for, and is how something waits for a person to unlock the store
	// rather than asking every few seconds whether they have.
	//
	// It is the third call a sealed instance answers, and has to be: waiting for
	// an unlock is only ever done by something looking at a sealed store. The
	// answer says which state was reached, or says that the wait ran out — a
	// timeout is an answer here rather than an error, because "still sealed after
	// ten minutes" is a fact about the store and not a failure of the call.
	AwaitState(context.Context, *connect.Request[ladulasv1.AwaitStateRequest]) (*connect.Response[ladulasv1.AwaitStateResponse], error)
	// KeyringStatus says whether this instance unlocks at login, and whether the
	// passphrase that decision I calls primary is still there behind it.
	KeyringStatus(context.Context, *connect.Request[ladulasv1.KeyringStatusRequest]) (*connect.Response[ladulasv1.KeyringStatusResponse], error)
	// SetUnlockAtLogin enrols the platform keychain, or forgets it again
	// (decision I). Enrolling copies the data encryption key into the keychain,
	// so it is the daemon's to do: it is the process holding that key.
	SetUnlockAtLogin(context.Context, *connect.Request[ladulasv1.SetUnlockAtLoginRequest]) (*connect.Response[ladulasv1.SetUnlockAtLoginResponse], error)
	// ListStoredKeys reports the keys this instance holds. A read, and it goes
	// through the daemon like every other one: the running instance is the only
	// thing that can answer without asking for a passphrase it has already been
	// given. The name says "stored" because KeyService.ListKeys next door is the
	// other question — what a peer is lending us.
	ListStoredKeys(context.Context, *connect.Request[ladulasv1.ListStoredKeysRequest]) (*connect.Response[ladulasv1.ListStoredKeysResponse], error)
	// GenerateKey makes a fresh key in the store. The agent offers it
	// immediately, since the process that added it is the process serving it.
	GenerateKey(context.Context, *connect.Request[ladulasv1.GenerateKeyRequest]) (*connect.Response[ladulasv1.GenerateKeyResponse], error)
	// ImportKey takes an existing OpenSSH private key, as 1Password exports it.
	// The bytes travel over the uid-checked socket and the daemon wipes them.
	ImportKey(context.Context, *connect.Request[ladulasv1.ImportKeyRequest]) (*connect.Response[ladulasv1.ImportKeyResponse], error)
	// RemoveKey forgets a key.
	RemoveKey(context.Context, *connect.Request[ladulasv1.RemoveKeyRequest]) (*connect.Response[ladulasv1.RemoveKeyResponse], error)
	// SetKeyEnabled stops or resumes offering a key through the agent.
	SetKeyEnabled(context.Context, *connect.Request[ladulasv1.SetKeyEnabledRequest]) (*connect.Response[ladulasv1.SetKeyEnabledResponse], error)
	// SetKeyAgentUse takes a key out of the agent's identity list, or puts it
	// back (decision T). Weaker than disabling it: the key goes on signing for
	// anything that names it, and stops being one of the identities ssh is handed
	// and told to try.
	SetKeyAgentUse(context.Context, *connect.Request[ladulasv1.SetKeyAgentUseRequest]) (*connect.Response[ladulasv1.SetKeyAgentUseResponse], error)
	// SendKey hands a portable key to a paired peer (decision S). The store
	// passphrase travels with the call and is checked before anything is sent:
	// the store is already open, so what it gates is deliberateness, and this is
	// the only management call in which that is the point.
	SendKey(context.Context, *connect.Request[ladulasv1.SendKeyRequest]) (*connect.Response[ladulasv1.SendKeyResponse], error)
	// ListKeyOffers reports the portable keys peers have handed this instance and
	// nobody has answered yet.
	ListKeyOffers(context.Context, *connect.Request[ladulasv1.ListKeyOffersRequest]) (*connect.Response[ladulasv1.ListKeyOffersResponse], error)
	// AnswerKeyOffer accepts an offered key into the store, or refuses it. A
	// refusal is a deletion: nothing is kept about a key this instance declined
	// to hold, since the only record worth having is on the side that sent it.
	AnswerKeyOffer(context.Context, *connect.Request[ladulasv1.AnswerKeyOfferRequest]) (*connect.Response[ladulasv1.AnswerKeyOfferResponse], error)
	// ListGrants reports the TTL grants that have not expired yet. A grant is the
	// approver's standing promise (§19) and lives in the store, so listing one is
	// the daemon's to answer like every other read.
	ListGrants(context.Context, *connect.Request[ladulasv1.ListGrantsRequest]) (*connect.Response[ladulasv1.ListGrantsResponse], error)
	// RevokeGrant takes a promise back before it runs out. The engine consults
	// the store on every decision, so a revocation through the daemon is in
	// force for the next request rather than for the next restart.
	RevokeGrant(context.Context, *connect.Request[ladulasv1.RevokeGrantRequest]) (*connect.Response[ladulasv1.RevokeGrantResponse], error)
	// ExtendGrant puts more time on a promise before it runs out: the same
	// promise, the same identifier, the same account of what it has covered,
	// running until later. One that was handed over is re-signed and delivered
	// to the machine holding it, and an extension that could not be delivered is
	// an extension that did not happen — the record here would otherwise say
	// more than the machine acting on it will do.
	ExtendGrant(context.Context, *connect.Request[ladulasv1.ExtendGrantRequest]) (*connect.Response[ladulasv1.ExtendGrantResponse], error)
	// ListDelegations reports the standing permissions this instance was given
	// by somebody else and is acting on itself (§19, decision P). They are the
	// other half of ListGrants and are deliberately a separate verb: a grant is
	// a promise made here and can be taken back here, and a delegation is one
	// made elsewhere that this instance can only stop using. An instance that
	// self-approves for an hour has to be able to say which promise it is
	// using, or the promise is one nobody here can audit.
	ListDelegations(context.Context, *connect.Request[ladulasv1.ListDelegationsRequest]) (*connect.Response[ladulasv1.ListDelegationsResponse], error)
	// BeginPairing displays a pairing code and waits for a peer to arrive. The
	// stream carries the code first and then the exchange as it happens; the
	// caller answers the confirmation with AnswerPairing.
	BeginPairing(context.Context, *connect.Request[ladulasv1.BeginPairingRequest], *connect.ServerStream[ladulasv1.PairingProgress]) error
	// PairWithPeer dials a peer that is displaying a code. Same stream, same
	// confirmation.
	PairWithPeer(context.Context, *connect.Request[ladulasv1.PairWithPeerRequest], *connect.ServerStream[ladulasv1.PairingProgress]) error
	// AnswerPairing settles the confirmation a PairingProgress asked for, by the
	// request id of the prompt. It is the surface a pairing command uses while it
	// is still on screen; the pairings verbs below are the surface for everything
	// that outlived the command that started it.
	AnswerPairing(context.Context, *connect.Request[ladulasv1.AnswerPairingRequest]) (*connect.Response[ladulasv1.AnswerPairingResponse], error)
	// ListPendingPairings reports the pairings that are under way: the ones this
	// instance's user has still to answer, and the ones already answered here
	// that are waiting for the other side. Nothing in the list expires, so
	// nothing leaves it except by being answered, withdrawn or completed.
	ListPendingPairings(context.Context, *connect.Request[ladulasv1.ListPendingPairingsRequest]) (*connect.Response[ladulasv1.ListPendingPairingsResponse], error)
	// AnswerPendingPairing records this side's answer to a pairing, whether or
	// not the command that started it is still running and whether or not the
	// peer can be reached. The answer is written down first and reconciled with
	// the peer afterwards.
	AnswerPendingPairing(context.Context, *connect.Request[ladulasv1.AnswerPendingPairingRequest]) (*connect.Response[ladulasv1.AnswerPendingPairingResponse], error)
	// WithdrawPairing calls an attempt off. It is a manual operation and the only
	// way a pending pairing is ever removed without an answer; the peer is told
	// if it can be reached, and finds out by asking if it cannot.
	WithdrawPairing(context.Context, *connect.Request[ladulasv1.WithdrawPairingRequest]) (*connect.Response[ladulasv1.WithdrawPairingResponse], error)
	// SetPeerDirections changes what a paired peer is allowed to do.
	SetPeerDirections(context.Context, *connect.Request[ladulasv1.SetPeerDirectionsRequest]) (*connect.Response[ladulasv1.SetPeerDirectionsResponse], error)
	// RenamePeer changes the name a peer is known by here. The name is this
	// side's own label, not the peer's, so nobody else is affected by it.
	RenamePeer(context.Context, *connect.Request[ladulasv1.RenamePeerRequest]) (*connect.Response[ladulasv1.RenamePeerResponse], error)
	// RevokePeer forgets a peer and drops any connection it is holding.
	RevokePeer(context.Context, *connect.Request[ladulasv1.RevokePeerRequest]) (*connect.Response[ladulasv1.RevokePeerResponse], error)
	// PublishProject marks a project as published to the peers that approve for
	// this instance (§6). It sends nothing (decision Q).
	PublishProject(context.Context, *connect.Request[ladulasv1.PublishProjectRequest]) (*connect.Response[ladulasv1.PublishProjectResponse], error)
	// ListPublications reports both halves of publishing: what this instance
	// publishes, and what it has read of what others publish.
	ListPublications(context.Context, *connect.Request[ladulasv1.ListPublicationsRequest]) (*connect.Response[ladulasv1.ListPublicationsResponse], error)
	// UnpublishProject stops publishing one of ours, or forgets what has been
	// read of somebody else's.
	UnpublishProject(context.Context, *connect.Request[ladulasv1.UnpublishProjectRequest]) (*connect.Response[ladulasv1.UnpublishProjectResponse], error)
	// SetAutoPublish turns the default of decision Q on or off: publish,
	// automatically, any project this instance sends an approval request for. It
	// is a setting rather than the only behaviour, because a machine that signs
	// in repositories it would rather not name should be able to say so.
	SetAutoPublish(context.Context, *connect.Request[ladulasv1.SetAutoPublishRequest]) (*connect.Response[ladulasv1.SetAutoPublishResponse], error)
	// WatchApprovals attaches a front end that answers prompts, and streams it
	// everything a human at this machine is supposed to see (decision Z).
	//
	// The stream is the registration: while it is open the caller is a local
	// approver in the engine's fan-out, exactly as an in-process tray window used
	// to be, and closing it takes the approver away. That is what makes the
	// desktop application a client of a daemon rather than a second copy of one —
	// the store, the keys and the agent socket stay in the one process that owns
	// them (decision L), and what crosses this socket is a card to draw and an
	// answer to carry back.
	//
	// A request in flight when the stream drops loses this approver: the daemon
	// withdraws the prompt from a screen that is no longer there, and whoever
	// else could answer — a paired phone, a policy, a grant — answers as they
	// would have. Restarting the front end does not re-raise it, because the
	// question has already been asked of everyone it could be asked of and is
	// waiting on the requester's own timeout.
	WatchApprovals(context.Context, *connect.Request[ladulasv1.WatchApprovalsRequest], *connect.ServerStream[ladulasv1.ApprovalPrompt]) error
	// AnswerApproval settles a request the stream raised. It is a separate call
	// rather than the other half of a bidirectional stream so that an answer is
	// an ordinary request with an ordinary error: a front end that could not be
	// told its answer arrived can say so, and one that answers a request that has
	// since been settled elsewhere is told which of the two happened.
	AnswerApproval(context.Context, *connect.Request[ladulasv1.AnswerApprovalRequest]) (*connect.Response[ladulasv1.AnswerApprovalResponse], error)
	// FetchRequestDiff asks the requester for the rest of a diff the caps cut
	// short, on behalf of the front end drawing the card (§5).
	//
	// It is the daemon that asks, because the connection to the requester is the
	// daemon's and the request is the daemon's; the front end knows only the
	// identifier it was handed.
	FetchRequestDiff(context.Context, *connect.Request[ladulasv1.FetchRequestDiffRequest]) (*connect.Response[ladulasv1.FetchRequestDiffResponse], error)
	// The doc browser, for a front end that is not in the daemon's process
	// (§6, decision Q). What a peer publishes is read through the peer channel
	// and kept in a cache sealed with the store key, so both halves of an answer
	// are the daemon's to give.
	//
	// The five calls are the five a browser makes: what is published, one
	// project's identity, a directory, a search, and a page. Every one of them
	// reports whether the answer came from the publishing machine or from what
	// has been read of it before, because under decision Q those are different
	// answers and a browser that blurred them would claim to know things it does
	// not.
	ListPeerProjects(context.Context, *connect.Request[ladulasv1.ListPeerProjectsRequest]) (*connect.Response[ladulasv1.ListPeerProjectsResponse], error)
	OpenPeerProject(context.Context, *connect.Request[ladulasv1.OpenPeerProjectRequest]) (*connect.Response[ladulasv1.OpenPeerProjectResponse], error)
	ListPeerDirectory(context.Context, *connect.Request[ladulasv1.ListPeerDirectoryRequest]) (*connect.Response[ladulasv1.ListPeerDirectoryResponse], error)
	SearchPeerProject(context.Context, *connect.Request[ladulasv1.SearchPeerProjectRequest]) (*connect.Response[ladulasv1.SearchPeerProjectResponse], error)
	ReadPeerPage(context.Context, *connect.Request[ladulasv1.ReadPeerPageRequest]) (*connect.Response[ladulasv1.ReadPeerPageResponse], error)
	// Reload re-reads the store and the policy from disk, which is the same thing
	// SIGHUP does to the daemon. It is here because the front end offers it in a
	// menu and a menu item may not depend on being able to signal a process.
	Reload(context.Context, *connect.Request[ladulasv1.ReloadRequest]) (*connect.Response[ladulasv1.ReloadResponse], error)
}

